// Stripe fires invoice.payment_failed once per retry, so attempt_count is the sequence position.
const cfg = $('Set config: brand, tone and final attempt').first().json;
const ev = $json.body || $json;
const inv = (ev.data && ev.data.object) || ev.object || ev;

const attempt = Number(inv.attempt_count || 1);
const finalAt = Number(cfg.finalAttempt) || 3;
const stage = attempt >= finalAt ? 'final' : (attempt <= 1 ? 'first' : 'second');

const minor = Number(inv.amount_remaining ?? inv.amount_due ?? 0);
const currency = String(inv.currency || 'usd').toUpperCase();
// Zero-decimal currencies must not be divided by 100 or the email quotes the wrong price.
const zeroDecimal = ['JPY', 'KRW', 'VND', 'CLP', 'ISK', 'UGX', 'XAF', 'XOF', 'BIF', 'DJF', 'GNF', 'KMF', 'MGA', 'PYG', 'RWF', 'VUV', 'XPF'];
const amount = zeroDecimal.includes(currency) ? minor : minor / 100;
const amountText = amount.toLocaleString('en-US', { minimumFractionDigits: zeroDecimal.includes(currency) ? 0 : 2, maximumFractionDigits: 2 }) + ' ' + currency;

const nextAttempt = inv.next_payment_attempt
  ? new Date(Number(inv.next_payment_attempt) * 1000).toISOString().slice(0, 10)
  : '';

const name = String(inv.customer_name || '').trim();
const email = String(inv.customer_email || '').trim();

return [{ json: {
  stage,
  attempt,
  finalAttempt: finalAt,
  customerEmail: email,
  customerName: name || 'there',
  hasEmail: !!email,
  amountText,
  currency,
  invoiceNumber: inv.number || inv.id || '',
  invoiceUrl: inv.hosted_invoice_url || '',
  nextAttempt,
  subscriptionId: inv.subscription || '',
  customerId: typeof inv.customer === 'string' ? inv.customer : ((inv.customer && inv.customer.id) || ''),
} }];

const cfg = $('Set config: brand, tone and final attempt').first().json;
const d = $json;
const schema = { type: 'object', additionalProperties: false, required: ['subject', 'body'], properties: {
  subject: { type: 'string' }, body: { type: 'string' } } };

const system = 'You write payment recovery emails for ' + cfg.brandName + '. This is involuntary churn: ' +
  'the card failed, the customer did not choose to leave. Never imply they cancelled, never shame them, ' +
  'never threaten. Assume an expired or replaced card is the most likely cause. Tone: ' + cfg.tone + '. ' +
  'Rules: state the amount exactly as given, never invent a date, a discount or an account detail, ' +
  'keep the body under 120 words, use exactly one call to action, and sign off as ' + cfg.fromName +
  ' at ' + cfg.brandName + '. Do not include the payment link in the body text, it is appended for you. ' +
  'Do not use em dashes.';

// The angle comes from the Set node on this branch, so the tone of each attempt is edited
// in the canvas rather than in code. The map is only a fallback if a branch is rewired.
const angles = {
  first: 'This is the first failed attempt. Be light and assume it is a simple card expiry. No urgency.',
  second: 'This is a repeat failure. Be a little more direct that action is needed, still friendly.',
  final: 'This is the final automatic attempt. Be clear that access is at risk after this, warmly and without threatening.',
};
const guidance = d.angle || angles[d.stage] || angles.second;

const user = [
  'STAGE: ' + d.stage + ' (attempt ' + d.attempt + ' of ' + d.finalAttempt + ')',
  'URGENCY: ' + (d.urgency || 'medium'),
  'GUIDANCE: ' + guidance,
  'CUSTOMER NAME: ' + d.customerName,
  'AMOUNT OUTSTANDING: ' + d.amountText,
  d.invoiceNumber ? 'INVOICE: ' + d.invoiceNumber : '',
  d.nextAttempt ? 'STRIPE WILL RETRY AUTOMATICALLY ON: ' + d.nextAttempt : 'NO FURTHER AUTOMATIC RETRY IS SCHEDULED.',
].filter(Boolean).join('\n');

return [{ json: { body: {
  model: cfg.model, max_tokens: 900, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: brand, tone and final attempt').first().json;
const d = $('Read the failed invoice').first().json;
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{}';

let ai = {};
try { ai = JSON.parse(text) || {}; } catch (e) {}

// A recovery email that fails to send is lost revenue, so fall back rather than error out.
const subject = ai.subject || ('Your ' + cfg.brandName + ' payment of ' + d.amountText + ' did not go through');
const opening = ai.body || ('Hi ' + d.customerName + ',\n\nWe tried to charge ' + d.amountText +
  ' and your card was declined. This is usually an expired or replaced card. You can update it using the link below.\n\nThanks,\n' +
  cfg.fromName + ' at ' + cfg.brandName);

const tail = [
  '',
  d.invoiceUrl ? 'Update your payment method: ' + d.invoiceUrl : 'Reply to this email and we will send you a secure payment link.',
  d.nextAttempt ? 'We will automatically try again on ' + d.nextAttempt + '.' : '',
  '',
  'Questions? Just reply, or write to ' + cfg.supportEmail + '.',
].filter((l) => l !== '' || true).join('\n');

const body = opening + '\n' + tail;

const ownerSubject = '[' + d.stage.toUpperCase() + '] Payment failed: ' + d.amountText + ' from ' + (d.customerEmail || 'unknown customer');
const ownerBody = [
  'A Stripe payment failed and attempt ' + d.attempt + ' of ' + d.finalAttempt + ' has now been sent.',
  '',
  '  Customer:     ' + d.customerName + ' <' + (d.customerEmail || 'no email on the invoice') + '>',
  '  Amount:       ' + d.amountText,
  '  Invoice:      ' + (d.invoiceNumber || 'unknown'),
  '  Subscription: ' + (d.subscriptionId || 'one-off charge'),
  '  Next retry:   ' + (d.nextAttempt || 'none scheduled, this was the last automatic attempt'),
  '',
  d.invoiceUrl ? 'Invoice: ' + d.invoiceUrl : '',
].filter(Boolean).join('\n');

return [{ json: {
  ...d, subject, body, ownerSubject, ownerBody,
  ownerEmail: cfg.ownerEmail,
  isFinal: d.stage === 'final',
} }];
